mp("MP-016","2024美国大选：特朗普胜出（positive于特朗普）。投票前一周选情胶着、民调互有领先，然胶着之下现任执政党候选承接通胀与执政包袱，摇摆面终向挑战者一方收束；以『相』字问卜所指之人（特朗普）气势在选前末段占先。时间窗：2024年11月5日投票定局。票差为接近量级，非大胜。","卡面事实：选情胶着、民调互有领先——无一方大优，取末段气势与执政包袱面定边；量级按胶着事实只给接近量级带。",0.55)

# ---------- write ----------
assert len(P)==60, len(P)
cm=ru=di=0
sizes={}
for cid,obj in P.items():
    s=json.dumps(obj,ensure_ascii=False,indent=1)
    path=os.path.join(OUT,cid+".json")
    with open(path,"w",encoding="utf-8") as f: f.write(s+"\n")
    sizes[cid]=os.path.getsize(path)
    t=obj["trigger"]
    cm+=t["changed_main"]; ru+=t["reserve_used"]; di+=t["disputed"]
print("written",len(sizes),"changed_main",cm,"reserve_used",ru,"disputed",di)
for k in sorted(sizes): print(k,sizes[k])
